syntax:
The core syntax involves relational operators (<, >, <=, >=) applied to pointers.  

```c++
int arr[] = {1, 2, 3, 4, 5};
int* ptr1 = arr;
int* ptr2 = arr + 2; 
bool result = (ptr1 < ptr2); // True
```

code_example:
#include <iostream>
#include <cstddef>
int main() {
  int arr[] = {10, 20, 30};
  int* ptr1 = arr;
  int* ptr2 = arr + 1;
  int* ptr3 = arr + 3; // One past the end
  std::cout << "ptr1 < ptr2: " << (ptr1 < ptr2) << std::endl;
  std::cout << "ptr2 < ptr3: " << (ptr2 < ptr3) << std::endl;
  std::cout << "ptr3 - ptr1: " << (ptr3 - ptr1) << std::endl; // Pointer arithmetic
  // Demonstrates potential undefined behavior: 
  // std::cout << "*ptr3: " << *ptr3 << std::endl; 
  return 0;
}
